src/top.js
const { rankings } = require('./rank');

function topN(entries, n) {
  return rankings(entries).slice(0, n);
}

module.exports = { topN };
src/rank.js
function rankings(entries) {
  return [...entries]
    .sort((a, b) => b.score - a.score)
    .map((e, i) => ({ rank: i + 1, player: e.player, score: e.score }));
}

module.exports = { rankings };
src/score.js
function compareScore(a, b) {
  const x = BigInt(a);
  const y = BigInt(b);
  return x < y ? -1 : x > y ? 1 : 0;
}

module.exports = { compareScore };
